INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'2e6f64989266867f','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Da der finnische Nachrichtendienst die Rote Armee als nicht einsatzbereit bezeichnete, ging der finnische Außenminister Eljas Erkko davon aus, die Sowjetunion werde keinen Krieg beginnen.',67716536,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-07 15:46:42','2106-02-07 06:28:15.999999');
