INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'5783be76bebacd07','winterwar','Kriegsopfer','Russische Quellen gehen heute von rund 127.000 Toten und Vermissten, sowie 265.000 Verwundeten und Kranken aus. Finnische Historiker nehmen noch höhere Zahlen an: rund 230.000–270.000 Tote und 200.000–300.000 Verwundete und Kranke, ein großer Teil davon durch Erfrierungen und mangelnde Versorgung mit Kleidung und Nahrungsmitteln.',67716536,171144946,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-07 15:46:42','2017-11-18 21:54:45');
