INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'acec92fdc9105e8e','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Auch die Einschätzung der Regierung, dass das Parlament keinen Gebietsabtretungen zustimmen würde, trugen zur ablehnenden Haltung Finnlands bei. Die sowjetische Seite hatte allerdings schon vor dem Ende der Verhandlungen eine militärische Option ins Auge gefasst.',67716536,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-07 15:46:42','2106-02-07 06:28:15.999999');
