INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'bcb9c1bc6bc47e13','winterwar','Kriegsopfer','Die Überlebenden pflegten scherzhaft zu sagen, dass das Land, das wir den Finnen nahmen, gerade ausreichte, um unsere während des Feldzugs gefallenen Offiziere und Soldaten zu begraben.“ Die Verluste der finnischen Streitkräfte umfassten nach finnischen Berichten rund 25.000 Tote und rund 43.500 Verwundete.',67716536,125967039,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-07 15:46:42','2013-12-31 09:20:48');
