INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'ef597db6f24c8652','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Cajanders Regierung, deren Einschätzung der Kriegsgefahr sich als unzutreffend erwiesen hatte, trat noch am selben Abend zurück und wurde am folgenden Tag durch eine auf breiterer parlamentarischer Grundlage stehende neue Regierung unter Risto Ryti , dem bisherigen Chef der Finnischen Zentralbank , ersetzt.',67716536,125967039,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-07 15:46:42','2013-12-31 09:20:48');
