INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'a5c5930080e00bb3','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Finnland leitete daraufhin eine Teilmobilmachung der Armee ein und versuchte erfolglos, sich mit Schweden zu verbünden.',125967039,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'be20bb4ca22dc6e9','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Die finnische Regierung unter Ministerpräsident Cajanderwar war zunächst bezüglich der Annahme der sowjetischen Forderungen gespalten, lehnte sie jedoch letztendlich ab. Als Konzession bot die finnische Regierung der Sowjetunion die Abtretung des Gebietes um den Ort Terijoki an, was von der Sowjetunion als ganz ungenügend abgelehnt wurde.',125967039,171144946,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2017-11-18 21:54:45');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'c58a56f3a8e8c9c4','winterwar','Kriegsopfer','Die Führung der Roten Armee gab an, die Finnen hätten zwischen 60.000 und 85.000 Todesopfer und 250.000 Verwundete zu beklagen.',125967039,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'c5efd445788e6e7b','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Cajanders Regierung, deren Einschätzung der Kriegsgefahr sich als unzutreffend erwiesen hatte, trat noch am selben Abend zurück; ihr folgte am folgenden Tag eine auf breiterer parlamentarischer Grundlage stehende neue Regierung unter Risto Ryti , dem bisherigen Chef der Finnischen Zentralbank .',125967039,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'d3ab62b760e244e2','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Dies hätte die Aufgabe sämtlicher finnischer Verteidigungsanlagen entlang der sogenannten Mannerheim-Linie bedeutet.',125967039,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'ee8540cc50b29d57','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Am 3. November 1939 unterstellte der sowjetische Außenminister Molotow in der Prawda Finnland kriegerische Absichten gegenüber dem Sowjetstaat.',125967039,271092734,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 09:20:48','2026-10-06 08:20:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'81e25adc47a19158','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Die finnische Regierung unter Ministerpräsident Cajander war zunächst bezüglich der Annahme der sowjetischen Forderungen gespalten, lehnte sie jedoch letztendlich ab. Als Konzession bot die finnische Regierung der Sowjetunion die Abtretung des Gebietes um den Ort Terijoki an, was von der Sowjetunion als ganz ungenügend abgelehnt wurde.',171144946,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-11-18 21:54:45','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'ef12eb3647faf7b7','winterwar','Kriegsopfer','Russische Quellen gehen heute von rund 127.000 Toten und Vermissten sowie 265.000 Verwundeten und Kranken aus. Finnische Historiker nehmen noch höhere Zahlen an: rund 230.000–270.000 Tote und 200.000–300.000 Verwundete und Kranke, ein großer Teil davon durch Erfrierungen und mangelnde Versorgung mit Kleidung und Nahrungsmitteln.',171144946,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-11-18 21:54:45','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'10da36ee6ee3b1c8','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Am Nachmittag stellte Präsident Kallio formell fest, dass sich das Land im Kriegszustand befinde.',218591747,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-29 09:45:19','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'a12b96674fd16c8c','winterwar','Kriegsopfer','In westlichen Quellen wird der Verdacht geäußert, sie seien nach dem Kriege größtenteils in Lagern des NKWD ermordet worden.',218591747,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-29 09:45:19','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'c7b67c8647d14cd6','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Die zukünftige finnisch-sowjetische Grenze sollte bis auf etwa dreißig Kilometer vor die Stadt Wiborg (Viipuri), Finnlands zweitgrößte Stadt, vorgeschoben werden.',218591747,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-29 09:45:19','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'4906852e355b8178','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Im September 1939 begann eine Mobilmachung für einen Feldzug gegen Finnland, die im November abgeschlossen war. Am 3. November 1939 unterstellte der sowjetische Außenminister Molotow in der Prawda Finnland kriegerische Absichten gegenüber dem Sowjetstaat.',271092734,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-06 08:20:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('de',51245,'e97f961ba6f9c6e8','winterwar','Verhandlungen mit Finnland und Kriegsbeginn','Ebenso forderte Stalin die Verpachtung der Halbinsel Hanko um die Stadt Hanko , die Überlassung von Inseln im finnischen Meerbusen und die Fischerhalbinsel an der Küste des Nördlichen Eismeeres .',271092734,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-06 08:20:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'152d83099cd07f54','winterwar','Background','The relationship between the Soviet Union and Finland was tense and frosty — both the two periods of forced russification at the turn of the century, and the legacy of the failed socialist rebellion in Finland contributed to a strong mutual distrust.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'21bd6c37f6cb5a16','winterwar','Background','This republic existed until March 12 , 1940 , and was eventually incorporated into the Russian Karelo-Finnish SSR .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'31d32958606ff236','winterwar','Background','Nazi Germany and the Soviet Union signed a mutual non-aggression pact, the Molotov-Ribbentrop Pact , on August 23 , 1939 .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'32bfbbfbeb0b392b','winterwar','Background','In 1932 , the Soviet Union signed a non-aggression pact with Finland.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'32e9932a57dcdffe','winterwar','Background','The Finns denied any responsibility for the attack and refused to give in to the demands.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'33dac2c10b7de537','winterwar','Background','A puppet regime was created in the occupied Finnish border town of Terijoki (now Zelenogorsk) on December 1 , 1939, under the auspices of the Finnish Democratic Republic and headed by Otto Ville Kuusinen for both diplomatic purposes (it immediately became the only government of Finland that was recognized by the Soviet Union) and for military ones (they hoped it would cause socialists in Finland\'s Army to defect ).',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'403303a3fac49650','winterwar','Background','In April 1938 or possibly even earlier, the Soviet Union started diplomatic negotiations with Finland, trying to improve the mutual defence against Germany.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'4a845d11d308a7a8','winterwar','Background','Finland had a long history of being a part of the Swedish kingdom when it was conquered by Russia in 1808 and turned into an autonomous buffer state to protect the Russian capital .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'4e0be8306fb17e43','winterwar','Background','The Soviet Union\'s primary concern was that Germany would use Finland as a bridgehead for the attack on Leningrad.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'578e40e1d5607419','winterwar','Background','Josef Stalin feared that Nazi Germany would attack sooner or later, and, with Soviet-Finnish border just 32 km away from Leningrad (now: Saint Petersburg), Finnish territory would have provided an excellent base for the attack - something that Stalin was keen to avoid.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'5eb2d24faaa83d26','winterwar','Background','More than a year passed without considerable progress and the political situation in Europe worsened.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'710fe04e527398ac','winterwar','Background','The pact also included a secret clause allocating the countries of Eastern Europe between the two signatories.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'72ab868f01e6b406','winterwar','Background','The German – Finnish ties remained close, although Finnish sympathy for the National Socialists was very sparse.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'789d0e70e9d19536','winterwar','Background','In exchange, the Soviet Union offered to Finland a large part of Karelia (twice as large, but less developed).',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'7aee25bc3466a2fc','winterwar','Background','On November 26 the Soviets staged the Shelling of Mainila , an incident in which Soviet artillery shelled areas near the Russian village of Mainila, then announced that a Finnish artillery attack had killed Soviet troops.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'963ca468e1bd870a','winterwar','Background','The Finnish government refused Soviet demands.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'a34079b54dc0892d','winterwar','Background','The agreement was reaffirmed in 1934 for ten years.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'a71c5b447501dc9d','winterwar','Armistice','Finland\'s losses had been limited to 22,830 men killed.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'a91cecdb9bb12b75','winterwar','Background','Only Germany\'s defeat in World War I hindered the establishment of a Germany-dependent monarchy under Frederick Charles of Hesse as King of Finland .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'becd32ad27e1cd86','winterwar','Background','On November 30 Soviet forces attacked with 23 divisions, totalling 450,000 men, which quickly reached the Mannerheim Line .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'c344814a01cd67ce','winterwar','Background','It also demanded that Finland lease the Hanko Peninsula to the USSR for 30 years for the creation of a naval base there.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'c8bbc6f899e26541','winterwar','Background','Finland was agreed to be in the Soviet " sphere of interest ".',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'cb8ab2dc36777fa9','winterwar','Background','Following the revolution that brought a Soviet government to power in Russia, Finland had declared itself independent on December 6 , 1917 .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'d8aa214eb969b4e6','winterwar','Background','The Soviet Union demanded that Finns should apologise for the incident and to move their forces 20-25 km from the border.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'db6fa63f9ec71bc6','winterwar','Background','In the subsequent Civil War German-trained Finnish Jäger troops and regular German troops played a crucial role.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'db7de0600d42de9b','winterwar','Background','It was not particularly successful.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'e11159af49b7bfd3','winterwar','Background','The German attack on Poland , September 1st , was followed by a Soviet invasion from the east.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'e6a6efcf2774cdc9','winterwar','Background','The Soviet Union used it as an excuse to withdraw from the non-aggression pact.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'e9ff4d4c63ac4e90','winterwar','Background','These strong ties were founded when Finland\'s underground independence movement during the First World War was supported by Imperial Germany .',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'ebaa2bb536777695','winterwar','Background','In a few weeks they had divided the country between them.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'ed4d89c8c7c039b4','winterwar','Background','In autumn 1939 after Germany\'s attack on Poland, the Soviet Union finally demanded that Finland agree to move the border 25 kilometres back from Leningrad, which was at that time only 32 kilometres from Finland.',33225464,335165674,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-30 07:19:35','2009-12-31 20:28:48');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'1414fa5472728a1a','winterwar','The shelling of Mainila','Doubt on the official Soviet version was cast only in the late 1980s, in the times of glasnost .',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'1cb1de99179ddb20','winterwar','The shelling of Mainila','However, the issue continued to divide Russian historiography even after the collapse of the Soviet Union .',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'44de4935d07aca55','winterwar','The shelling of Mainila','On 26 November, a border incident was reported near the village of Mainila .',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'8e9d10e74e18d194','winterwar','The shelling of Mainila','A Soviet border guard post had been shelled by an unknown party resulting, according to Soviet reports, in the deaths of four and injuries of nine border guards.',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'94d4f58e1d86e0e3','winterwar','The shelling of Mainila','The Soviet Union then claimed that the Finnish response was hostile and renounced the non-aggression pact on 28 November.',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'be7f2ccda8f2ef3f','winterwar','The shelling of Mainila','In the following years, Soviet historiography described the incident as a Finnish provocation.',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'c4f3cf45b2773bf9','winterwar','The shelling of Mainila','Research conducted by several Finnish and Russian historians later concluded that the shelling was carried out from the Soviet side of the border by an NKVD unit with the purpose of providing the Soviet Union with a casus belli and a pretext to withdraw from the non-aggression pact .',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'dbe29de34ae94416','winterwar','The shelling of Mainila','Soviet Foreign Minister Vyacheslav Molotov claimed it was a Finnish artillery attack and demanded that Finland apologise for the incident and move its forces beyond a line 20–25 kilometres away from the border.',335165674,588505617,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2013-12-31 10:53:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'e45e5ec41c0ef2b7','winterwar','The shelling of Mainila','Finland denied responsibility for the attack, rejected the demands, and called for a joint Finnish–Soviet commission to examine the incident.',335165674,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-31 20:28:48','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'1776a93ffc8cee93','winterwar','Shelling of Mainila','Soviet Foreign Minister Vyacheslav Molotov claimed that it was a Finnish artillery attack and demanded that Finland apologise for the incident and move its forces beyond a line 20–25 km (12–16 mi) away from the border.',588505617,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 10:53:32','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'1f33ab1bc0efa872','winterwar','Shelling of Mainila','Russian President Vladimir Putin said on 14 March 2013 at a meeting with military historians that Stalin launched the war to "correct mistakes" made in drawing the border with Finland after the 1917 Bolshevik revolution.',588505617,817645920,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-31 10:53:32','2017-12-29 18:23:52');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'65f3dfd0a1df499a','winterwar','Shelling of Mainila','Molotov claimed that the incident was a Finnish artillery attack and demanded that Finland apologize for the incident and move its forces beyond a line 20–25 km (12–16 mi) away from the border.',817645920,1062771208,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2021-12-30 12:19:01');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'6876b7bb9cb0837e','winterwar','Shelling of Mainila','In 2013, Russian President Vladimir Putin stated at a meeting with military historians that the USSR launched the Winter War to "correct mistakes" made in determining the border with Finland after 1917.',817645920,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'74231835d592bd0a','winterwar','Shelling of Mainila','Finland denied responsibility for the attack, rejected the demands and called for a joint Finnish–Soviet commission to examine the incident.',817645920,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'7c75a288e1641b04','winterwar','Shelling of Mainila','On 26 November 1939, an incident was reported near the Soviet village of Mainila close to the border with Finland: A Soviet border guard post had been shelled by an unknown party resulting, according to Soviet reports, in the deaths of four and injuries of nine border guards.',817645920,1062771208,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2021-12-30 12:19:01');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'8813eda80ffd1136','winterwar','Shelling of Mainila','In turn, the Soviet Union claimed that the Finnish response was hostile, renounced the non-aggression pact and severed diplomatic relations with Finland on 28 November.',817645920,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'97db06ea67216b69','winterwar','Shelling of Mainila','In the following years, Soviet historiography described the incident as Finnish provocation.',817645920,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'a2c4d88384318659','winterwar','Shelling of Mainila','Research conducted by several Finnish and Russian historians later concluded that the shelling was a false flag operation carried out from the Soviet side of the border by an NKVD unit with the purpose of providing the Soviet Union with a casus belli and a pretext to withdraw from the non-aggression pact .',817645920,1062771208,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2021-12-30 12:19:01');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'b2383d8223b22853','winterwar','Shelling of Mainila','However, the issue continued to divide Russian historiography even after the collapse of the Soviet Union in 1991.',817645920,1062771208,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2021-12-30 12:19:01');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'b253c5b747804897','winterwar','Shelling of Mainila','Doubt on the official Soviet version was cast only in the late 1980s, during the policy of glasnost .',817645920,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-29 18:23:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'09fc1182152c478b','winterwar','Shelling of Mainila and Soviet intentions','Opinion on the scale of the initial Soviet invasion decision is divided: some sources conclude that the Soviet Union had intended to conquer Finland in full, and cite the establishment of the puppet Finnish Communist government and the Molotov–Ribbentrop Pact\'s secret protocols as proof of their conclusions.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'2917d047eb838ed7','winterwar','Shelling of Mainila and Soviet intentions','Soviet war games held in March 1938 and 1939 had been based on a scenario where border incidents taking place at the village of Mainila would have sparked the war. Molotov claimed that the incident was a Finnish artillery attack and demanded that Finland apologise for the incident and move its forces beyond a line 20–25 km (12–16 mi) away from the border.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'4567aa3d1b7d0069','winterwar','Finnish, Russian and other languages','Aptekar, Pavel. "Casus Belli: о Майнильском инциденте, послужившим поводом, для начала "Зимней войны" 1939–40 гг" [ Casus Belli: about the Mainila incident, which served as a pretext for the beginning of the "Winter War" of 1939–40 ] .',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'5d39b39eb7c283fd','winterwar','Shelling of Mainila and Soviet intentions','He quotes Molotov, who commented in November 1939 on the regime-change plan to a Soviet ambassador that the new government "will not be Soviet, but one of a democratic republic.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'5f624cb45f18c3a8','winterwar','Shelling of Mainila and Soviet intentions','Rather, the objective was to gain Finnish territory and reinforce Soviet influence in the region.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'698bf151aac8f8b5','winterwar','Shelling of Mainila and Soviet intentions','Bradley Lightbody wrote that the "entire Soviet aim had been to make the Soviet border more secure." In 2002, Russian historian A.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'77a0c719e1c2c7dc','winterwar','Shelling of Mainila and Soviet intentions','Claiming Stalin to have little expectations for such deal, while playing time for the ongoing mobilization.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'8b02a253ae71cc2b','winterwar','Shelling of Mainila and Soviet intentions','Hungarian historian István Ravasz wrote that the Soviet Central Committee had set out in 1939 that the former borders of the Tsarist Empire were to be restored—including Finland.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'8b907aa72c06d882','winterwar','Shelling of Mainila and Soviet intentions','Stating the objective as being securing Finland from being used as a staging ground by means of regime change.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'8e9d10e74e18d194','winterwar','The shelling of Mainila','A Soviet border guard post had been shelled by an unknown party resulting, according to Soviet reports, in the deaths of four and injuries of nine border guards.',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'935864305a0aec38','winterwar','Shelling of Mainila and Soviet intentions','On 26 November 1939, an incident was reported near the Soviet village of Mainila , close to the border with Finland.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'93de1745c0f8cc42','winterwar','Shelling of Mainila and Soviet intentions','Research conducted by several Finnish and Russian historians later concluded that the shelling was a false flag operation, because there were no artillery units placed there at the time, and it was carried out from the Soviet side of the border by an NKVD unit with the purpose of providing the Soviet Union with a casus belli and a pretext to withdraw from the non-aggression pact.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'ad441c202dc47b4b','winterwar','Shelling of Mainila and Soviet intentions','The issue continued to divide Russian historiography even after the collapse of the Soviet Union in 1991.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'aeb4ecf48bd8b8c1','winterwar','Shelling of Mainila and Soviet intentions','Nobody is going to set up Soviets over there, but we hope it will be a government we can come to terms with as to ensure the security of Leningrad." According to Russian historian Yuri Kilin , the Soviet terms encompassed the strongest fortified approaches of the Finnish defences for a reason.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'bca5b3c7b4e4cbe9','winterwar','Shelling of Mainila and Soviet intentions','Chubaryan stated that no documents had been found in Russian archives that support a Soviet plan to annex Finland.',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'c01a47639b4bd40f','winterwar','Shelling of Mainila and Soviet intentions','He stated that "the strongest argument" against a Soviet intention of full conquest is that it did not happen in either 1939 or during the Continuation War in 1944—even though Stalin "could have done so with comparative ease".',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'c2c5bf6788114439','winterwar','Shelling of Mainila and Soviet intentions','Trotter asserted that Stalin\'s objective was to secure Leningrad\'s flank from a possible German invasion through Finland.',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'ca4afd33a47917d1','winterwar','Finland','According to revised estimates in 2005 by Finnish historians, 25,904 people died or went missing and 43,557 were wounded on the Finnish side during the war. Finnish and Russian researchers have estimated that there were 800–1,100 Finnish prisoners of war , of whom between 10 and 20 percent died.',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'f19117b5f3e49bba','winterwar','Shelling of Mainila and Soviet intentions','American political scientist Dan Reiter stated that the USSR "sought to impose a regime change" and thus "achieve absolute victory".',1062771208,1384334162,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2026-11-07 19:50:21');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'fa112e7af564c09d','winterwar','Shelling of Mainila and Soviet intentions','Others argue against the idea of a complete Soviet conquest.',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'fcbf47f32f7a7f25','winterwar','Shelling of Mainila and Soviet intentions','American historian William R.',1062771208,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 12:19:01','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('en',33924,'35604292efe77b1a','winterwar','Shelling of Mainila and Soviet intentions','He demanded that Finland apologise for the incident and to move its forces beyond a line 20–25 km (12–16 mi) from the border.',1384334162,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-07 19:50:21','2106-02-07 06:28:15.999999');
