INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('et',43646,'e2f2740a2f9ceea7','winterwar','Sõja algus','Meie [Punaarmee] väeosad lõid soomlased tagasi nende territooriumile, tekitades neile kaotusi.',7010191,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2025-11-03 16:25:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('et',43646,'e57f4496e0a418be','winterwar','Sõja algus','Samal ööl kell 3.15 avati Karjala maakitsusel Raasuli külast kuulipildujatuli.',7010191,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2025-11-03 16:25:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('et',43646,'f5e848a8410266c9','winterwar','Sõja algus','Kell 4 hommikul üks Soome jalaväekompanii püüdis rünnata meie piiriposti Termolovo külas, mis asub Karjala maakitsusel.',7010191,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2025-11-03 16:25:52','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'1f26c3827e1ff621','winterwar','Sodan alku','Neuvostoliitto muodosti myös Otto Wille Kuusisen johtaman Terijoen hallituksen suomalaisista kommunisteista ja katsoi täten käyvänsä sotaa ainoastaan porvarillisia vihollisia vastaan.',658274,7751713,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-31 19:28:39','2009-12-20 16:23:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'35b6981b53575018','winterwar','Sodan alku','Presidentti Kyösti Kallio luki eduskunnan päätöksen sotatilasta kello 13.30. Neuvostoliiton ulkoministeri Molotov piti myöhään illalla radiopuheen, jossa hän kertoi neuvostohallituksen antaneen Puna-armeijalle määräyksen varmistua valtion ulkoisesta turvallisuudesta.',658274,7751713,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-31 19:28:39','2009-12-20 16:23:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'39bcc8f5bad262e5','winterwar','Osapuolten tappiot','Neuvostoliitto ilmoitti sodan jälkeen tappioikseen 49 000 kaatunutta, mutta nykyään tiedetään varmuudella tämän luvun olevan liian pieni.',658274,7751713,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-31 19:28:39','2009-12-20 16:23:32');
