INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'03f66096f5243d8d','winterwar','Propagandahyökkäys sodan aattopäivinä','K. Cajanderia solvattiin ”tunkiolla kiekuvaksi kukoksi”, ”kiemurtelevaksi käärmeeksi”, ”ahneeksi pikkupedoksi”, ”imperialistien sätkynukeksi” ja ”päällään seisovaksi sirkusklovniksi”.',20199251,24373824,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2026-11-13 10:39:22');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'062fc3699d0fdb3c','winterwar','Osapuolten tappiot','Suomalaisten tappiot talvisodassa olivat 26 662 sotatoimissa kuollutta ja noin tuhat siviiliä.',20199251,24373824,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2026-11-13 10:39:22');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'160b75a84de7a90a','winterwar','Propagandahyökkäys sodan aattopäivinä','Suomalaisten yleisen mielipiteen sanottiin vastustavan Suomen valtuuskunnan asennetta Moskovan neuvotteluissa ja Yhdistyneen kuningaskunnan hallituksen yllyttävän taloudellisen mahtiasemansa turvin Suomen hallitusta sotaisiin seikkailuihin.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'2f9f2f3e3fabbd14','winterwar','Propagandahyökkäys sodan aattopäivinä','Suomen Moskovan-lähettiläs Aarno Yrjö-Koskinen , joka oli kutsuttu saman päivän iltana ulkoministeri Vjatšeslav Molotovin luo, aikoi esittää tälle vastalauseensa Pravdan kirjoituksesta, mutta ennen kuin Yrjö-Koskinen sai puheenvuoron, Molotov luki hänelle Neuvostoliiton hallituksen Suomen hallitukselle osoittaman jyrkän nootin Mainilan laukausten johdosta.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'3a55d766f44284c2','winterwar','Propagandahyökkäys sodan aattopäivinä','Hitlerin Saksa oli kuitenkin menetellyt aivan samalla tavoin kolme kuukautta aiemmin ennen hyökkäystä Puolaan, ja puna-armeija puolestaan oli viivyttänyt marssiaan Itä-Puolaan, kunnes oli voitu todeta Puolan hallitusvallan jääneen vaille käyttäjää ja ukrainalaisten ja valkovenäläisten ”kaipaavan suojelua”.',20199251,24373824,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2026-11-13 10:39:22');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'3bbc32b7ed436fe3','winterwar','Propagandahyökkäys sodan aattopäivinä','Kampanjan tarkoituksena oli suureksi osaksi Neuvostoliiton väestön mielialan muokkaaminen kannattamaan Suomeen tehtävää hyökkäystä.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'4c681261e3ac5327','winterwar','Propagandahyökkäys sodan aattopäivinä','Kirjoituksissa kerrottiin muun muassa suomalaisten sotilaiden karkaamisista varuskunnistaan ja kapinoinnista upseereitaan kohtaan, reserviläisten ja suojeluskuntalaisten välisistä kahakoista, jotka olivat vaatineet kuolonuhreja, sekä eräänä ääriesimerkkinä Tampereella muka toteutetusta 1 500 ateistin likvidoinnista.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'5b16678eb19d9ac0','winterwar','Propagandahyökkäys sodan aattopäivinä','Kun Molotov 28. marraskuuta ilmoitti Kremliin jälleen kutsutulle Yrjö-Koskiselle Neuvostoliiton irtisanovan yksipuolisesti Suomen kanssa tekemänsä hyökkäämättömyyssopimuksen ”Suomen vihamielisen asenteen johdosta”, Yrjö-Koskinen huomautti, ettei sopimusta ollut mahdollista irtisanoa ennen vuotta 1945.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'6f9a59de30a3e29a','winterwar','Propagandahyökkäys sodan aattopäivinä','Lehdissä julkaistiin tahallisesti ja tarkoituksellisesti väritettyjä, Suomen näkökulmasta käsittämättömiltä tuntuneita uutisia.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'92e703953be69f46','winterwar','Propagandahyökkäys sodan aattopäivinä','Suomalaisten ja neuvostojohdon välisten neuvottelujen katkettua Neuvostoliiton sanomalehdistö aloitti marraskuun puolivälissä 1939 voimakkaan Suomea vastaan suunnatun arvostelu- ja parjauskampanjan.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'938b3c2d1fd43026','winterwar','Propagandahyökkäys sodan aattopäivinä','Neuvostoliiton kommunistisen puolueen pää-äänenkannattajassa Pravdassa 26. marraskuuta 1939 julkaistussa kirjoituksessa pääministeri A.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'aab5f383bc4504f0','winterwar','Propagandahyökkäys sodan aattopäivinä','Tätä taustaa vasten oli yhdentekevää, oliko Mainilassa ammuttu vai ei.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
