INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'ee3cdc1efd48c1e6','winterwar','Propagandahyökkäys sodan aattopäivinä','Suomalaiset, jotka tunsivat tulleensa loukatuiksi, eivät pysyneet mukana tässä tapahtumaketjussa, vaan pohtivat oikeudellisia näkökohtia, joilla ei ollut todellisuuden kanssa enää paljonkaan tekemistä.',20199251,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-30 08:02:55','2106-02-07 06:28:15.999999');
