INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'7d6c8a721d965a3d','winterwar','Propagandahyökkäys sodan aattopäivinä','K. Cajanderia solvattiin ”tunkiolla kiekuvaksi kukoksi”, ”kiemurtelevaksi käärmeeksi”, ”ahneeksi pikkupedoksi”, ”imperialistien sätkynukeksi” ja ”päällään seisovaksi sirkuspelleksi”.',24373824,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-13 10:39:22','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'8519fbaf22d33984','winterwar','Suomen ja Neuvostoliiton neuvottelut aluemuutoksista','Neuvostoliitto lavasti 26. marraskuuta 1939 Mainilan laukaukset , joilla se perusteli sotaa puolustuksellisena toimenpiteenä.',24373824,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-13 10:39:22','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'b0519d93ef8689af','winterwar','Osapuolten tappiot','Ville Kivimäen Murtuneet mielet -kirjan mukaan mielen häiriöistä kärsiviä ei hoidettu sodan aikana juuri lainkaan, eikä heille tavallisesti myönnetty sotainvalidikorvauksia.',24373824,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-13 10:39:22','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('fi',1256,'e6c7e507e8219384','winterwar','Osapuolten tappiot','Täysin varmaa tietoa kaatuneista neuvostoliittolaisista ei ole. Everstiluutnantti Grigori Fedotovitš Krivošejevin 1990-luvulla johtama venäläinen tutkimusryhmä tutki kaikki neuvostoarkistoissa olleet tiedot Neuvostoliiton sodissa kärsimistä tappioista (tutkimus on julkaistu englanniksi nimellä Soviet Casualties and Combat Losses in the Twentieth Century ).',24373824,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-13 10:39:22','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'3ce4b25b1b33cf64','winterwar','Предыстория','26 ноября произошёл Майнильский инцидент , 28 ноября СССР разорвал пакт о ненападении с Финляндией, 30 ноября советским войскам был дан приказ перейти границу и наступать.',605412,20807535,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-20 17:50:46','2009-12-23 12:59:44');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'cb9f7f9441d18cbb','winterwar','Потери Финляндии','В результате потери Карельского перешейка Финляндия лишилась возможности построить действенную систему обороны и с момента завершения войны находилась под постоянной угрозой: в любой момент советские войска могли снова вторгнуться на её территорию и за счёт подавляющего преимущества в численности провести успешную наступательную операцию.',605412,20807535,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-20 17:50:46','2009-12-23 12:59:44');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'fb544297da45ec2e','winterwar','Потери Финляндии','Финляндия потеряла убитыми, по советским данным, 48 243 человека, по официальным финским — 26 662 человека; значительную часть территории, в том числе второй по величине город страны — Выборг ; систему оборонительных сооружений.',605412,20807535,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-12-20 17:50:46','2009-12-23 12:59:44');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'512d14be3cefc45b','winterwar','Предыстория','В тот же день произошёл артиллерийский обстрел территории СССР у населённого пункта Майнила , предположительно инсценированный советской стороной, — что подтверждается соответствующими распоряжениями Маннергейма, уверенного в неизбежности советской провокации и потому предварительно отведшего войска от границы на расстояниие, исключающее возникновение недоразумений.',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'5d2f1b32af01372a','winterwar','Поводы для войны','Маннергейм, располагавший как главнокомандующий наиболее достоверными данными об инциденте под Майнила, сообщает : …И вот провокация, которую я ожидал с середины октября, свершилась.',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'5e6ad194b3ab6909','winterwar','Поводы для войны','26 ноября Советский Союз организовал провокацию, известную ныне под названием «Выстрелы в Майнила»… Во время войны 1941—1944 годов пленные русские детально описали, как была организована неуклюжая провокация… В советских учебниках по истории СССР, ответственность за начало войны возлагалась на Финляндию и страны Запада: «Некоторого временного успеха империалисты смогли добиться в Финляндии.',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9ddc168adc431db1','winterwar','Поводы для войны','Спустя много лет бывший начальник ленинградского бюро ТАСС Анцелович рассказал, что пакет с текстом сообщения о «майнильском инциденте» и надписью «вскрыть по особому распоряжению» он получил за две недели до происшествия .',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'c6adf9d5479d4024','winterwar','Статьи','84. Аптекарь П. «Выстрелов не было» — утверждает российский архивист: [Документы об инциденте в Майниле] // Родина. — 1995. — N 12. — С.',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'e7844d34921cc789','winterwar','Поводы для войны','Официальным поводом к войне стал « Майнильский инцидент »: 26 ноября 1939 года советское правительство обратилось к правительству Финляндии с официальной нотой, в которой заявлялось, что в результате артиллерийского обстрела, совершённого с территории Финляндии, погибли четверо и были ранены девять советских военнослужащих.',20807535,60401111,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2013-12-30 18:13:32');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'f3974c27e6bfb779','winterwar','Статьи','16. Куманев Г. «Что у вас там произошло в Майниле»?: [О провокации, с которой началась война] / Беседу с учёным записал Л.',20807535,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-23 12:59:44','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'04aee7b50e31decc','winterwar','Повод к войне и разрыв отношений','В тот же день советская авиация бомбила и обстреляла из пулеметов Хельсинки; при этом, в результате ошибки летчиков, пострадали в основном жилые рабочие кварталы.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'0d400f4be22cfdb2','winterwar','Повод к войне и разрыв отношений','Им удалось в конце 1939 года спровоцировать финских реакционеров на войну против СССР » .',60401111,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'23f678863f9d43ce','winterwar','Повод к войне и разрыв отношений','Советские войска, имея строгое приказание не поддаваться провокации, воздержались от ответного обстрела» .',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'31bafcd386c4be1e','winterwar','Повод к войне и разрыв отношений','Принимай нас, Суоми — красавица, В ожерелье прозрачных озёр!',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'3c66da1bd1b138fa','winterwar','Повод к войне и разрыв отношений','Утром 30 ноября был сделан и последний шаг. Как говорилось в официальном сообщении, «по приказу Главного Командования Красной Армии, ввиду новых вооруженных провокаций со стороны финской военщины, войска Ленинградского военного округа в 8 часов утра 30 ноября перешли границу Финляндии на Карельском перешейке и в ряде других районов» . .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'48c46072908294dd','winterwar','Повод к войне и разрыв отношений','Ярким примером является песня « Принимай нас, Суоми-красавица »: Мы приходим помочь вам расправиться, Расплатиться с лихвой за позор.',60401111,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'557383cc3147fbe9','winterwar','Повод к войне и разрыв отношений','Всего было произведено семь орудийных выстрелов, в результате чего убито трое рядовых и один младший командир, ранено семь рядовых и двое из командного состава.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'62d32249f9dc7776','winterwar','Повод к войне и разрыв отношений','Между последними шёл разговор о реализации уже принятого решения — предъявлении Финляндии ультиматума; тогда же Сталин заявил, что Куусинен возглавит новую Карело-Финскую ССР с присоединением «освобожденных» финских районов.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'67cd2a309ca5669a','winterwar','Повод к войне и разрыв отношений','Сталин считал «что после того, как Финляндии будут предъявлены ультимативные требования территориального характера и в случае, если она их отвергнет, придется начать военные действия» , заметив: «сегодня начнется это дело» .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'7a794d3fd21a30d3','winterwar','Повод к войне и разрыв отношений','При этом официального объявления войны так и не последовало.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'7f8010be2a4b15bd','winterwar','Повод к войне и разрыв отношений','Тем временем финские пограничники спешно провели расследование инцидента, тем более что пограничные посты были свидетелями обстрела.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'7fbb924fcde20e8a','winterwar','Повод к войне и разрыв отношений','Маннергейм, располагавший как главнокомандующий наиболее достоверными данными об инциденте под Майнила, сообщает: …И вот провокация, которую я ожидал с середины октября, свершилась.',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'889d904c81441434','winterwar','Повод к войне и разрыв отношений','Вечером 29 ноября финляндский посланник в Москве Аарно Юрьё-Коскинен ( фин. Aarno Yrjö-Koskinen ) был вызван в Народный комиссариат иностранных дел, где заместитель наркома В.',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'88c902d099cfa487','winterwar','Повод к войне и разрыв отношений','При этом следует отметить, что внутренняя советская пропаганда не афишировала Майнильский инцидент, служивший откровенно формальным поводом: она делала акцент на то, что Советский Союз совершает освободительный поход в Финляндию, чтобы помочь финским рабочим и крестьянам свергнуть гнет капиталистов.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'89bf755a8592a643','winterwar','Повод к войне и разрыв отношений','Сам Хрущев считал (в согласии с настроением Сталина, как он утверждает), что «достаточно громко сказать им <финнам>, если же не услышат, то разок выстрелить из пушки, и финны поднимут руки вверх, согласятся с требованиями» .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'8a133ec0ea16abda','winterwar','Повод к войне и разрыв отношений','В ответ на протесты европейских дипломатов Молотов заявил, что советские самолеты сбрасывали на Хельсинки хлеб для голодающего населения (после чего советские бомбы стали называть в Финляндии «Молотовскими хлебными корзинами») .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'958740bf34a70377','winterwar','Повод к войне и разрыв отношений','В тот же день финны отметили нападение на их пограничников у Петсамо .',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9654479362352102','winterwar','Повод к войне и разрыв отношений','Это означало разрыв дипломатических отношений.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'99088af7c2ae812e','winterwar','Повод к войне и разрыв отношений','Ответная нота СССР гласила: «отрицание со стороны правительства Финляндии факта возмутительного артиллерийского обстрела финскими войсками советских войск, повлекшего за собой жертвы, не может быть объяснено иначе, как желанием ввести в заблуждение общественное мнение и поиздеваться над жертвами обстрела. <…> Отказ правительства Финляндии отвести войска, совершившие злодейский обстрел советских войск, и требование об одновременном отводе финских и советских войск, исходящие формально из принципа равенства сторон, изобличают враждебное желание правительства Финляндии держать Ленинград под угрозой» .',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'995e12be582c1a53','winterwar','Повод к войне и разрыв отношений','Нота была составлена в умеренных выражениях и требовала отвода финских войск на 20-25 км от границы во избежание повторения инцидентов.',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9b1bd68e32f333d0','winterwar','Повод к войне и разрыв отношений','При этом упоминание в тексте «невысокого солнышка осени » дает повод к предположению, что текст был написан загодя в расчёте на более раннее начало войны .',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'a0f0e332bcd3681a','winterwar','Повод к войне и разрыв отношений','В ней говорилось, что, ввиду сложившегося положения, ответственность за которое ложится на правительство Финляндии, правительство СССР признало необходимым немедленно отозвать из Финляндии своих политических и хозяйственных представителей.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'ac5853856a89a0eb','winterwar','Московские переговоры о территории Финляндии','В тот же день произошёл артиллерийский обстрел территории СССР у населённого пункта Майнила , инсценированный советской стороной — что также подтверждается соответствующими распоряжениями Маннергейма, уверенного в неизбежности советской провокации и потому предварительно отведшего войска от границы на расстояние, исключающее возникновение недоразумений.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'aee58bd8e3b84a17','winterwar','Повод к войне и разрыв отношений','В советской пропаганде, а затем и историографии ответственность за начало войны возлагалась на Финляндию и страны Запада: « Некоторого временного успеха империалисты смогли добиться в Финляндии.',60401111,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b298beee209fc295','winterwar','Повод к войне и разрыв отношений','Официальным поводом к войне стал « Майнильский инцидент »: 26 ноября 1939 года советское правительство обратилось к правительству Финляндии с официальной нотой, в которой заявлялось, что «26 ноября, в 15 часов 45 минут, наши войска, расположенные на Карельском перешейке у границы Финляндии, около села Майнила, были неожиданно обстреляны с финской территории артиллерийским огнем.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b4b33edcf0b15721','winterwar','Литература','84. Аптекарь П. «Выстрелов не было» — утверждает российский архивист: [Документы об инциденте в Майниле] // Родина. — 1995. — № 12. — С.',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b4d54e45815da93a','winterwar','Повод к войне и разрыв отношений','Когда я лично побывал 26 октября на Карельском перешейке, генерал Неннонен заверил меня, что артиллерия полностью отведена за линию укреплений, откуда ни одна батарея не в силах произвести выстрел за пределы границы… …Нам не пришлось долго ждать претворения в жизнь слов Молотова, произнесённых на московских переговорах: «Вести разговоры теперь наступит очередь солдат».',60401111,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b6bb27efdb30e856','winterwar','Военные','Итого погибло 26 662 финских военнослужащих.',60401111,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'c6ffc59822fa7101','winterwar','Повод к войне и разрыв отношений','26 ноября Советский Союз организовал провокацию, известную ныне под названием «Выстрелы в Майнила»… Во время войны 1941—1944 годов пленные русские детально описали, как была организована неуклюжая провокация… Никита Хрущёв рассказывает, что поздней осенью (по смыслу именно 26 ноября) он обедал на квартире у Сталина вместе с Молотовым и Куусиненом.',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'d1149a8b1c616efb','winterwar','Повод к войне и разрыв отношений','И. Кулик (артиллерист) для организации провокации.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'d115c402fbebc24a','winterwar','Повод к войне и разрыв отношений','Хрущев, Молотов и Куусинен долго сидели у Сталина, ожидая ответа финнов; все были уверены, что Финляндия испугается и согласится на советские условия .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'da94ca32dc7b68b9','winterwar','Повод к войне и разрыв отношений','Ответной нотой финны заявили, что обстрел был зафиксирован финскими постами, выстрелы были произведены с советской стороны, по наблюдениям и оценкам финнов с расстояния около 1,5-2 км на юго-восток от места падения снарядов, что на границе у финнов есть только пограничные войска и нет орудий, тем более дальнобойных, но что Хельсинки готов приступить к переговорам об обоюдном отводе войск и начать совместное расследование инцидента.',60401111,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'eaf53727cf530462','winterwar','Повод к войне и разрыв отношений','СССР объявлял о своем выходе из Пакта о ненападении с Финляндией, мотивируя это тем, что сосредоточение финских войск под Ленинградом создает угрозу городу и является нарушением пакта. .',60401111,89813748,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2017-12-23 09:24:26');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'f927bc1f7d653f52','winterwar','Повод к войне и разрыв отношений','В Ленинград был заранее послан замнаркома обороны маршал Г.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'fc52893485428afb','winterwar','Повод к войне и разрыв отношений','П. Потёмкин вручил ему новую ноту.',60401111,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2013-12-30 18:13:32','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'1192d630b875ca82','winterwar','Повод к войне и разрыв отношений','Сталин считал, «что после того, как Финляндии будут предъявлены ультимативные требования территориального характера и в случае, если она их отвергнет, придется начать военные действия» , заметив: «сегодня начнётся это дело» .',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'1c0302a3a88f7bc4','winterwar','Повод к войне и разрыв отношений','Официальным поводом к войне стал « Майнильский инцидент »: 26 ноября 1939 года советское правительство обратилось к правительству Финляндии с официальной нотой, в которой заявлялось, что «26 ноября, в 15 часов 45 минут, наши войска, расположенные на Карельском перешейке у границы Финляндии, около села Майнила, были неожиданно обстреляны с финской территории артиллерийским огнём.',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'215b5bb4de19f965','winterwar','Повод к войне и разрыв отношений','Хрущёв, Молотов и Куусинен долго сидели у Сталина, ожидая ответа финнов; все были уверены, что Финляндия испугается и согласится на советские условия .',89813748,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'36162c8cd37c338b','winterwar','Повод к войне и разрыв отношений','Утром 30 ноября был сделан и последний шаг. Как говорилось в официальном сообщении, «по приказу Главного Командования Красной Армии, ввиду новых вооружённых провокаций со стороны финской военщины, войска Ленинградского военного округа в 8 часов утра 30 ноября перешли границу Финляндии на Карельском перешейке и в ряде других районов» .',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'513ed91cdd7c9c4d','winterwar','Повод к войне и разрыв отношений','При этом следует отметить, что внутренняя советская пропаганда не афишировала Майнильский инцидент, служивший откровенно формальным поводом: она делала акцент на то, что Советский Союз совершает освободительный поход в Финляндию, чтобы помочь финским рабочим и крестьянам свергнуть гнёт капиталистов.',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'65fdeb0cf4f665fe','winterwar','Повод к войне и разрыв отношений','Сам Хрущёв считал (в согласии с настроением Сталина, как он утверждает), что «достаточно громко сказать им <финнам>, если же не услышат, то разок выстрелить из пушки, и финны поднимут руки вверх, согласятся с требованиями» .',89813748,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'7622f404ac16db5a','winterwar','Повод к войне и разрыв отношений','СССР объявил о своем выходе из Пакта о ненападении с Финляндией, мотивируя это тем, что сосредоточение финских войск под Ленинградом создает угрозу городу и является нарушением пакта .',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9dcc381890970288','winterwar','Повод к войне и разрыв отношений','26 ноября Советский Союз организовал провокацию, известную ныне под названием «Выстрелы в Майнила»… Во время войны 1941—1944 годов пленные русские детально описали, как была организована неуклюжая провокация… Н.',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'a16f582fd7d89cf5','winterwar','Повод к войне и разрыв отношений','С. Хрущёв рассказывает, что поздней осенью (по смыслу именно 26 ноября) он обедал в квартире Сталина вместе с Молотовым и Куусиненом.',89813748,119008872,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2021-12-31 13:24:12');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b0ce3db696b58eb7','winterwar','Повод к войне и разрыв отношений','Между последними шёл разговор об осуществлении уже принятого решения — предъявлении Финляндии ультиматума; тогда же Сталин заявил, что Куусинен возглавит новую Карело-Финскую ССР с присоединением «освобождённых» финских районов.',89813748,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'d74b5b02e646bb53','winterwar','Переговоры в Москве (октябрь—ноябрь 1939). Территориальный вопрос','В тот же день произошёл артиллерийский обстрел территории СССР у населённого пункта Майнила .',89813748,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'d76cb339cb190833','winterwar','Повод к войне и разрыв отношений','В ответ на протесты европейских дипломатов Молотов заявил, что советские самолёты сбрасывали на Хельсинки хлеб для голодающего населения (после чего советские бомбы стали называть в Финляндии «Молотовскими хлебными корзинами») .',89813748,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'e9933435c4941f71','winterwar','Повод к войне и разрыв отношений','В тот же день советская авиация бомбила и обстреляла из пулемётов Хельсинки; при этом в результате ошибки лётчиков пострадали в основном жилые рабочие кварталы.',89813748,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2017-12-23 09:24:26','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'0129ba24fb15e088','winterwar','Майнильский инцидент','Официальным поводом к войне стал Майнильский инцидент.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'07b09eb9ae0069c6','winterwar','Майнильский инцидент','26 ноября 1939 года советское правительство обратилось к правительству Финляндии с официальной нотой, в которой заявлялось: «26 ноября, в 15 часов 45 минут, наши войска, расположенные на Карельском перешейке у границы Финляндии, около села Майнила, были неожиданно обстреляны с финской территории артиллерийским огнём.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'1c54064c04eae888','winterwar','Майнильский инцидент','Принимай нас, Суоми-красавица, В ожерелье прозрачных озёр!',119008872,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'1d07d28e7cdc2e50','winterwar','Майнильский инцидент','Н. С. Хрущёв рассказывает, что поздней осенью (по смыслу именно 26 ноября) он обедал в квартире Сталина вместе с Молотовым и Куусиненом.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'276fb13974dfee76','winterwar','Майнильский инцидент','По поводу этих событий Маннергейм впоследствии писал: …И вот провокация, которую я ожидал с середины октября, свершилась.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'5455eaef00ead66f','winterwar','Майнильский инцидент','Ответная нота СССР гласила: «отрицание со стороны правительства Финляндии факта возмутительного артиллерийского обстрела финскими войсками советских войск, повлёкшего за собой жертвы, не может быть объяснено иначе, как желанием ввести в заблуждение общественное мнение и поиздеваться над жертвами обстрела. <…> Отказ правительства Финляндии отвести войска, совершившие злодейский обстрел советских войск, и требование об одновременном отводе финских и советских войск, исходящие формально из принципа равенства сторон, изобличают враждебное желание правительства Финляндии держать Ленинград под угрозой» .',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'585f62cd9600ad2a','winterwar','Майнильский инцидент','СССР объявил о своем выходе из Пакта о ненападении с Финляндией, мотивируя это тем, что сосредоточение финских войск под Ленинградом создаёт угрозу городу и является нарушением пакта .',119008872,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'6ef756106ff2d213','winterwar','Майнильский инцидент','Сталин считал, «что после того, как Финляндии будут предъявлены ультимативные требования территориального характера и в случае, если она их отвергнет, придётся начать военные действия» , заметив: «сегодня начнётся это дело» .',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9a62864b675b76f0','winterwar','Майнильский инцидент','Нота была составлена в умеренных выражениях и требовала отвода финских войск на 20—25 км от границы во избежание повторения инцидентов.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b39d612850cd7f8b','winterwar','Майнильский инцидент','Ответной нотой финны заявили, что обстрел был зафиксирован финскими постами, выстрелы были произведены с советской стороны, по наблюдениям и оценкам финнов с расстояния около 1,5—2 км на юго-восток от места падения снарядов, что на границе у финнов есть только пограничные войска и нет орудий, тем более дальнобойных, но что Хельсинки готов приступить к переговорам об обоюдном отводе войск и начать совместное расследование инцидента.',119008872,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b8b9b4502a4c9280','winterwar','Майнильский инцидент','При этом внутренняя советская пропаганда не афишировала Майнильский инцидент, служивший формальным поводом: она делала акцент на то, что Советский Союз совершает освободительный поход в Финляндию, чтобы помочь финским рабочим и крестьянам свергнуть гнёт капиталистов.',119008872,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'dabebd078264bfba','winterwar','Майнильский инцидент','26 ноября Советский Союз организовал провокацию, известную ныне под названием «Выстрелы в Майнила»… Во время войны 1941—1944 годов пленные русские детально описали, как была организована неуклюжая провокация…',119008872,155688701,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-31 13:24:12','2026-10-18 18:22:09');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'0458e9a6cd1fd654','winterwar','Майнильский инцидент','СССР объявил о своём выходе из Пакта о ненападении с Финляндией, мотивируя это тем, что сосредоточение финских войск под Ленинградом создаёт угрозу городу и является нарушением пакта .',155688701,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-18 18:22:09','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'2145b84e56a5d75e','winterwar','Майнильский инцидент','Сам Хрущёв считал (в согласии с настроением Сталина, как он утверждает), что «достаточно громко сказать им <финнам> , если же не услышат, то разок выстрелить из пушки, и финны поднимут руки вверх, согласятся с требованиями» .',155688701,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-18 18:22:09','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'7a80558b01cf8545','winterwar','Майнильский инцидент','26 ноября Советский Союз организовал провокацию, известную ныне под названием «Выстрелы в Майнила». <…> Во время войны 1941—1944 годов пленные русские детально описали, как была организована неуклюжая провокация…',155688701,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-18 18:22:09','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'9eb6ef9ab839c7de','winterwar','Майнильский инцидент','Когда я лично побывал 26 октября на Карельском перешейке, генерал Неннонен заверил меня, что артиллерия полностью отведена за линию укреплений, откуда ни одна батарея не в силах произвести выстрел за пределы границы <…> Нам не пришлось долго ждать претворения в жизнь слов Молотова, произнесённых на московских переговорах: «Вести разговоры теперь наступит очередь солдат».',155688701,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-18 18:22:09','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('ru',33700,'b36db6e825131f80','winterwar','Военные','Итого погибло 26 662 финских военнослужащих .',155688701,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-10-18 18:22:09','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'107a41dc5f941a63','winterwar','Bakgrund','Under det finska inbördeskriget (frihetskriget) hade ryska trupper deltagit på den röda sidan och trots att bolsjevikerna snabbt erkände Finlands självständighetsförklaring var det klart att Moskva helst hade sett att de röda vunnit inbördeskriget.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'17621298aabc9321','winterwar','Bakgrund','De finländska soldaterna hade dock kanske den bästa vinterutbildningen i Europa och var mycket goda skyttar.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'2478912959e169e8','winterwar','Bakgrund','1932 hade ett treårigt icke-aggressionsavtal tecknats vilket förlängdes på tio år 1934 .',1245782,24434380,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2013-12-11 09:18:44');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'25457110637b8a37','winterwar','Bakgrund','Som motprestation skulle Finland få delar av Östkarelen samt få tillåtelse att befästa Åland .',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'46f6276339ff3b31','winterwar','Bakgrund','Några veckor senare sade Sovjet upp icke-aggressionsavtalet från 1932 samtidigt som finländska gränspatruller kunde se hur sovjetiska trupper drogs samman till gränsområdet.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'4ef3a87b0c3333b6','winterwar','Bakgrund','Finlands utrikesminister Eljas Erkko drog dock parallellen mellan de ryska kraven och hur Tyskland, efter att Tjeckoslovakien gjort landavträdelser, ändå ockuperade landet 1938.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'550bb45630fe949f','winterwar','Bakgrund','1938 hade Sovjet vid kontakter med regeringen gjort klart att man önskade något slags avtal om militärt bistånd mellan de två länderna - ryska militärbaser och rätt för Röda armén att ingripa för att "skydda" Finlands oberoende.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'5e1b4794ebe61af6','winterwar','Bakgrund','Vad gäller styrkeförhållandet var Sovjetunionen överlägset både till personal, beväpning och utrustning.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'6ca7afebde751c2f','winterwar','Bakgrund','Den finsk-sovjetiska gränsen på Karelska näset skulle flyttas västerut.',1245782,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'7e712819fcad8d0c','winterwar','Bakgrund','Efter att Sovjetunionen och Tyskland slutit Molotov-Ribbentroppakten hade Sovjet en mycket stor handlingsfrihet vad gäller Baltikum och Finland.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'815112bf51db058a','winterwar','Bakgrund','Under hösten 1939 tvingades Estland , Lettland och Litauen gå med på att tillåta ryska militärbaser i sina länder.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'833beb042c6d832c','winterwar','Bakgrund','Under 1930-talet hade Finlands regering i sin utrikespolitik understrukit sin nordiska orientering och att vid internationella konflikter hålla på landets neutralitet.',1245782,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'9511dfd5701ffe1f','winterwar','Bakgrund','Under sommaren 1939 hade den s.k. Mannerheim-linjen slutförts, en linje av färdigställda befästningspunkter över Karelska näset.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'9a188833cbedf65e','winterwar','Bakgrund','Förtroendet ökades inte heller av Aunusexpeditionen 1920 där finländsk militär besatte delar av Östkarelen .',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'9e4db522ab4a24ad','winterwar','Bakgrund','Finlands armé bestod av ungefär 130 000 soldater, 40 stridsvagnar och ca.150 flygplan medan Röda armén anföll med 525 000 man, 2000 stridsvagnar och 800 flygplan.',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'a3da12b474c7b941','winterwar','Bakgrund','Petersburg under inbördeskriget i Ryssland .',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'b1fdd464a0decf94','winterwar','Bakgrund','Sovjetflottan skulle få använda Lappvik nära Hangö som ankarplats.',1245782,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'b34c4441dece03b1','winterwar','Bakgrund','Befästningar på Karelska näset skulle förstöras Finland skulle överlämna västra delen av Fiskarhalvön vid Norra ishavet .',1245782,10703574,NULL,'snapshot',0,0,FROM_BASE64(''),'2005-11-21 08:08:35','2009-12-18 09:53:31');
