INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'0e2e32998fd3c359','winterwar','Bakgrund','Därmed stod det klart att bolsjevikerna och Ryska SFSR som samma år erkänt Finlands självständighetsförklaring helst hade sett att de socialistiska "röda gardena" vunnit inbördeskriget.',10703574,42191553,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2017-12-06 15:25:40');
