INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'2c3447956d93be57','winterwar','Bakgrund','Finlands utrikesminister Eljas Erkko drog dock parallellen mellan de sovjetiska kraven och hur Tyskland, efter att Tjeckoslovakien gjort landavträdelser, ändå ockuperat landet 1938.',10703574,24434380,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2013-12-11 09:18:44');
