INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'3407ce3f7fdc14c0','winterwar','Bakgrund','Under hösten 1939 tvingades Estland , Lettland och Litauen gå med på att tillåta sovjetiska militärbaser inom sina gränser.',10703574,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'3bef7bbec3024162','winterwar','Skotten i Mainila','Finlands armé bestod i det första skedet av 200 000 man, 32 stridsvagnar och 119 flygplan medan Röda armén som till största delen bestod av nyrekryterade soldater anföll med 460 000 man, 1 500 stridsvagnar och 1 000 flygplan.',10703574,42191553,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2017-12-06 15:25:40');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'40dead4daa662fd4','winterwar','Bakgrund','Som kompensation skulle Finland tilldelas delar av Östkarelen samt få tillåtelse att befästa Åland .',10703574,42191553,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2017-12-06 15:25:40');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'45c86e5c5fc1f61f','winterwar','Skotten i Mainila','Vad gäller styrkeförhållandet var Sovjetunionen överlägset både till numerär, beväpning och utrustning.',10703574,42191553,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2017-12-06 15:25:40');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'56e1bbfa48186506','winterwar','Bakgrund','Det bevisas främst av den quislingregering som Sovjetmakten upprättade i Terijoki och som började ge ut proklamationer till hela Finlands folk, samt att Sovjetarmén försökte tränga in längs hela Finlands gräns, och inte bara på de platser man krävt under förhandlingarna.',10703574,42191553,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2017-12-06 15:25:40');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'5b3a65139509da9c','winterwar','Skotten i Mainila','Denna linje var avsedd att vara ett omfattande nätverk av färdigställda befästningspunkter över Karelska näset.',10703574,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2009-12-18 09:53:31','2106-02-07 06:28:15.999999');
