INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'b26969ab91e5bed1','winterwar','Bakgrund','Finland hade också samarbetat med den tyska militären, bland annat i utvecklande av ubåtsvapnet.',49911062,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2021-12-06 14:15:17','2106-02-07 06:28:15.999999');
INSERT INTO claim (lang,page_id,h,topic_id,section,text,born_rev,died_rev,died_comment,time_precision,has_ref,had_ref,emb,row_start,row_end) VALUES ('sv',23612,'349205d2a9b53f32','winterwar','Bakgrund','Sedan Sovjetunionen och Nazityskland slutit Molotov–Ribbentroppakten hade Sovjetunionen en betydande stor handlingsfrihet vad gäller Baltikum och Finland, då dessutom västmakterna England och Frankrike var uppbundna i krig med Tyskland.',59855895,NULL,NULL,'snapshot',0,0,FROM_BASE64(''),'2026-11-12 13:18:44','2106-02-07 06:28:15.999999');
